"""Build KUF Stage A using only pinned extracts and saved public sources. No network/Git mutation."""
import csv,json,pathlib,hashlib,datetime,collections,itertools,math,re
R=pathlib.Path(__file__).resolve().parent
PERIOD='2027-01-01/2028-12-31'
NOW=datetime.datetime.now(datetime.timezone.utc).isoformat()
def digest(b):return hashlib.sha256(b).hexdigest()
def canonical(x):return json.dumps(x,ensure_ascii=False,sort_keys=True,separators=(',',':'),allow_nan=False).encode()
def readable(x):
 if isinstance(x,dict):return {k:readable(v) for k,v in x.items()}
 if isinstance(x,list):return [readable(v) for v in x]
 if isinstance(x,str) and re.search('[А-Яа-яЁё]',x):
  return re.sub(r'(?<=[А-Яа-яЁё])(?=[A-Za-z0-9])|(?<=[A-Za-z0-9])(?=[А-Яа-яЁё])',' ',x)
 return x
def writej(name,obj):(R/name).write_text(json.dumps(readable(obj),ensure_ascii=False,indent=2,allow_nan=False)+'\n')
def readcsv(name):return list(csv.DictReader((R/'inputs'/name).open()))
def writecsv(name,rows,fields=None):
 assert rows,'No empty placeholder tables'
 fields=fields or list(dict.fromkeys(k for row in rows for k in row))
 with (R/name).open('w',newline='') as f:
  w=csv.DictWriter(f,fieldnames=fields);w.writeheader()
  for row in rows:w.writerow({k:json.dumps(readable(v),ensure_ascii=False) if isinstance(v,(list,dict)) else 'UNKNOWN' if v is None else readable(v) for k,v in row.items()})
pins=json.loads((R/'source_pins.json').read_text())
receipts=json.loads((R/'source_receipts.json').read_text())+json.loads((R/'pdf_receipts.json').read_text())
for f in sorted((R/'sources').glob('RW-QUOTE-*.json')):
 q=json.loads(f.read_text());receipts.append({'source_id':q['source_id'],'url':q['url'],'retrieved_at':q['retrieved_at'],'method':q['method'],'status':q['status'],'json_path':str(f.relative_to(R)),'raw_sha256':digest(f.read_bytes()),'raw_bytes':f.stat().st_size,'coverage':q['coverage']})
S={r['source_id']:r for r in receipts}
evidence=[];assumptions=[]
